using System;using System.IO;using System.Linq;using System.Text;using System.Drawing;using System.Threading;using System.Threading.Tasks;using System.Diagnostics;using System.Collections.Generic;using System.Windows.Forms;using System.Windows.Media.Media3D;
namespace GearLab {public static class WebPreferences672Tests {
 static int checks;static void Check(bool value,string message){checks++;if(!value)throw new Exception(message);}static void Pump(int milliseconds){var timer=Stopwatch.StartNew();while(timer.ElapsedMilliseconds<milliseconds){Application.DoEvents();Thread.Sleep(10);}}
 static T Get<T>(Task<T> task){var timer=Stopwatch.StartNew();while(!task.IsCompleted&&timer.Elapsed.TotalSeconds<45)Pump(10);if(!task.IsCompleted)throw new Exception("WebView response timeout");return task.GetAwaiter().GetResult();}
 static Dictionary<string,object> Info(RobotWebViewport web){return (Dictionary<string,object>)CADDocument.Serializer().DeserializeObject(CADDocument.Serializer().Deserialize<string>(Get(web.Inspect())));}
 public static int Run(string folder){Directory.CreateDirectory(folder);var old=AppSettings.Current;string oldProfile=Environment.GetEnvironmentVariable("GEARLAB_PROFILE_DIR");try{Environment.SetEnvironmentVariable("GEARLAB_PROFILE_DIR",Path.Combine(Path.GetFullPath(folder),"profile"));AppSettings.Current=new AppSettings{Quality=GearQuality.Быстрый};using(var form=new Form{Text="WebView preferences verification",Size=new Size(900,650),ShowInTaskbar=false})using(var web=new RobotWebViewport()){form.Controls.Add(web);AppSettings.Current=new AppSettings{Quality=GearQuality.Подробный,SnapEnabled=true,SnapStep=2.5};web.ApplyAppearance();form.Show();var timer=Stopwatch.StartNew();while(!web.Ready&&timer.Elapsed.TotalSeconds<50)Pump(20);Check(web.Ready,"WebView ready");Pump(250);var initial=Info(web);Check(Convert.ToInt32(initial["quality"])==2,"latest pre-initialization quality delivered");Check(Convert.ToDouble(initial["translationSnap"])==2.5,"initial snap delivered");web.Part("cube","Cube",MeshDocument.Cube().ToScene(),Matrix3D.Identity,Color.Orange);web.Fit();Pump(1500);int clears=web.ClearCount,uploads=web.PartUploadCount;double width=Convert.ToDouble(Info(web)["width"]);var ratios=new List<double>();var pixels=new List<int>();
 foreach(var quality in new[]{GearQuality.Быстрый,GearQuality.Обычный,GearQuality.Подробный}){var settings=AppSettings.Current.Clone();settings.Quality=quality;settings.SnapEnabled=quality!=GearQuality.Быстрый;settings.SnapStep=quality==GearQuality.Обычный?3.25:.5;AppSettings.Commit(settings);Pump(250);var current=Info(web);Check(Convert.ToInt32(current["quality"])==(int)quality,"quality change reaches active WebView");ratios.Add(Convert.ToDouble(current["pixelRatio"]));pixels.Add(Convert.ToInt32(current["canvasWidth"]));Check(settings.SnapEnabled?Convert.ToDouble(current["translationSnap"])==settings.SnapStep:current["translationSnap"]==null,"snap toggle/step reach TransformControls");Check(Convert.ToInt32(current["parts"])==1&&web.ClearCount==clears&&web.PartUploadCount==uploads,"view preferences reuse loaded meshes");Check(Math.Abs(Convert.ToDouble(current["width"])-width)<1e-8,"view preferences preserve world framing");}
 Check(ratios[0]<ratios[1]&&ratios[1]<ratios[2]&&pixels[0]<pixels[1]&&pixels[1]<pixels[2],"fast/normal/detailed resize the actual drawing buffer");Pump(800);long before=Convert.ToInt64(Info(web)["renderFrames"]);Pump(500);long after=Convert.ToInt64(Info(web)["renderFrames"]);Check(after-before<=1,"preference update settles back to idle");form.Close();File.WriteAllText(Path.Combine(folder,"web-preferences672-results.txt"),"PASS "+checks+" assertions: initial preferences, quality resolution, snapping, mesh reuse, framing and idle redraw.",Encoding.UTF8);}return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"web-preferences672-error.txt"),ex.ToString(),Encoding.UTF8);return 1;}finally{AppSettings.Current=old;Environment.SetEnvironmentVariable("GEARLAB_PROFILE_DIR",oldProfile);}}
}}
